func _init() -> void:
	var failures: int = 0
	var sm := SaveManager.new()

	# --- Case 1: empty inventory, empty unlocked_levels ---
	var d1 := GameSaveData.new()
	d1.player_position = Vector2.ZERO
	d1.last_played = 0
	var h1a: String = sm.compute_hash(d1)
	sm.save_to_disk(d1, "user://edge_empty", false)
	var d1_loaded: GameSaveData = sm.load_from_disk("user://edge_empty")
	if d1_loaded == null or d1_loaded.inventory.size() != 0 or d1_loaded.unlocked_levels.size() != 0:
		printerr("FAIL: empty round-trip")
		failures += 1
	if d1_loaded != null and sm.compute_hash(d1_loaded) != h1a:
		printerr("FAIL: empty hash mismatch")
		failures += 1

	# --- Case 2: many items, verify order and field equality ---
	var d2 := GameSaveData.new()
	d2.player_position = Vector2(100.0, 200.0)
	for i in range(5):
		var it := ItemData.new()
		it.id = "item_%d" % i
		it.quantity = i * 7
		it.rarity = i % 5
		d2.inventory.append(it)
	d2.unlocked_levels = PackedStringArray(["a", "b", "c", "d"])
	d2.last_played = 999
	var h2: String = sm.compute_hash(d2)
	sm.save_to_disk(d2, "user://edge_many", true)  # binary
	var d2_loaded: GameSaveData = sm.load_from_disk("user://edge_many.res")
	if d2_loaded == null:
		printerr("FAIL: many-items .res load returned null")
		failures += 1
	else:
		if d2_loaded.inventory.size() != d2.inventory.size():
			printerr("FAIL: many-items size mismatch")
		for i in range(min(d2.inventory.size(), d2_loaded.inventory.size())):
			var li: Resource = d2_loaded.inventory[i]
			var ri: Resource = d2.inventory[i]
			if li.id != ri.id or li.quantity != ri.quantity or li.rarity != ri.rarity:
				printerr("FAIL: many-items field mismatch at ", i)
		if sm.compute_hash(d2_loaded) != h2:
			printerr("FAIL: many-items hash mismatch")
			failures += 1

	# --- Case 3: hash collision resistance - same items in different order ---
	var d3 := GameSaveData.new()
	d3.player_position = d2.player_position
	d3.unlocked_levels = d2.unlocked_levels
	d3.last_played = d2.last_played
	for it in d2.inventory:
		d3.inventory.append(it)
	d3.inventory.reverse()
	if sm.compute_hash(d3) == h2:
		printerr("FAIL: order not captured by hash")
		failures += 1

	# --- Case 4: hash sensitivity to a single field ---
	var d4 := GameSaveData.new()
	d4.player_position = d2.player_position
	d4.inventory = d2.inventory.duplicate()
	d4.unlocked_levels = d2.unlocked_levels
	d4.last_played = d2.last_played + 1
	if sm.compute_hash(d4) == h2:
		printerr("FAIL: last_played change not detected")
		failures += 1

	# --- Case 5: a path with no extension loads either format ---
	# edge_many was saved as .res above; loading the bare path must find .res
	# (or .tres, but we have neither .tres under that base, so this should fail
	# and return null cleanly).
	var d5 = sm.load_from_disk("user://edge_many")
	if d5 != null:
		printerr("UNEXPECTED: load_from_disk with no ext and no .tres found ", d5)
		failures += 1

	# --- Cleanup ---
	DirAccess.remove_absolute("user://edge_empty.tres")
	DirAccess.remove_absolute("user://edge_many.res")

	if failures == 0:
		print("EDGE ALL OK")
	else:
		print("EDGE FAILURES: ", failures)
	quit(0 if failures == 0 else 1)
